Avoid uninitialized memory
As reported by https://bugs.chromium.org/p/oss-fuzz/issues/detail?id=16977, https://bugs.chromium.org/p/oss-fuzz/issues/detail?id=16979 and https://bugs.chromium.org/p/oss-fuzz/issues/detail?id=16982


diff --git a/src/mat4.c b/src/mat4.c
index ee41263..578c70a 100644
--- a/src/mat4.c
+++ b/src/mat4.c
@@ -371,7 +371,7 @@ Mat_VarRead4(mat_t *mat,matvar_t *matvar)
             break;
         case MAT_C_SPARSE:
             matvar->data_size = sizeof(mat_sparse_t);
-            matvar->data      = malloc(matvar->data_size);
+            matvar->data      = calloc(1, matvar->data_size);
             if ( NULL != matvar->data ) {
